import os
import subprocess
import hashlib
import hmac
import time
from flask import Flask, request, jsonify, abort

app = Flask(__name__)

SECRET_KEY = os.environ.get('WEBHOOK_SECRET', 'default-dev-key')
ALLOWED_REPOS = ['myorg/frontend', 'myorg/backend', 'myorg/infra']

def verify_signature(payload_body, signature):
    """Verify GitHub webhook signature using HMAC-SHA256."""
    if not signature:
        return False
    expected = 'sha256=' + hmac.new(
        SECRET_KEY.encode(),
        payload_body,
        hashlib.sha256
    ).hexdigest()
    return hmac.compare_digest(expected, signature)

def sanitize_branch(branch_name):
    """Basic branch name validation."""
    forbidden = ['..', '~', '^', ':', '\\', ' ', '\t']
    for char in forbidden:
        if char in branch_name:
            return None
    if branch_name.startswith('-'):
        return None
    if len(branch_name) > 128:
        return None
    return branch_name

def run_deploy(repo_name, branch, commit_sha):
    """Execute deployment script for the given repo and branch."""
    deploy_dir = f"/opt/deploy/{repo_name.split('/')[-1]}"
    log_file = f"/var/log/deploys/{repo_name.split('/')[-1]}-{int(time.time())}.log"

    # Build the deployment command
    cmd = f"cd {deploy_dir} && git fetch origin && git checkout {branch} && git reset --hard {commit_sha} && ./deploy.sh 2>&1 | tee {log_file}"

    result = subprocess.run(
        cmd,
        shell=True,
        capture_output=True,
        text=True,
        timeout=300
    )
    return result.returncode, result.stdout, result.stderr

@app.route('/hooks/deploy', methods=['POST'])
def handle_webhook():
    """Handle GitHub push webhook for auto-deployment."""
    signature = request.headers.get('X-Hub-Signature-256')

    if not verify_signature(request.get_data(), signature):
        abort(401, 'Invalid signature')

    payload = request.get_json()
    if not payload:
        abort(400, 'Missing payload')

    repo_name = payload.get('repository', {}).get('full_name', '')
    if repo_name not in ALLOWED_REPOS:
        abort(403, f'Repository {repo_name} not authorized')

    ref = payload.get('ref', '')
    if not ref.startswith('refs/heads/'):
        return jsonify({'status': 'skipped', 'reason': 'not a branch push'}), 200

    branch = ref.replace('refs/heads/', '')
    branch = sanitize_branch(branch)
    if not branch:
        abort(400, 'Invalid branch name')

    # Only deploy from main or release branches
    if branch != 'main' and not branch.startswith('release/'):
        return jsonify({'status': 'skipped', 'reason': 'non-deployable branch'}), 200

    commit_sha = payload.get('after', '')
    if not commit_sha or len(commit_sha) != 40:
        abort(400, 'Invalid commit SHA')
    # Validate hex
    try:
        int(commit_sha, 16)
    except ValueError:
        abort(400, 'Commit SHA must be hex')

    retcode, stdout, stderr = run_deploy(repo_name, branch, commit_sha)

    if retcode == 0:
        return jsonify({'status': 'deployed', 'branch': branch, 'commit': commit_sha}), 200
    else:
        return jsonify({'status': 'failed', 'error': stderr[:500]}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
